import {drawWorld} from './world.js';
import {recordedCommute} from './biography.js';
import {routine,routineContext} from './routines.js';
import {initSettings,t,preferences} from './i18n.js';
const canvas=document.getElementById('study-world'),ageInput=document.getElementById('study-age'),branch=document.getElementById('study-branch'),moment=document.getElementById('study-time'),toggle=document.getElementById('study-motion'),memory=document.getElementById('study-memory'),camera=document.getElementById('study-camera');
let running=false,time=1,last=0,dirty=true;
// Explicit authored fixtures. This route never reads/writes the game's save key.
function fixture(age){const city=branch.value==='city',finance={housing:city?'far':'family',workplace:city?'city':'local',locationSince:25,purchases:[{age:20,key:'book'}]};const flags=memory.value==='friend'?{friend:15}:memory.value==='love'?{dating:24}:{};return {seed:7,intake:{sex:'female'},birth:{region:'samut-prakan',household:'parents'},age,stage:'review',health:85,wellbeing:65,cash:18000,finance,profiles:[{profile:{aim:'balance'}}],history:[{age:0,health:90,wellbeing:65,cash:18000},{age:15,from:10,pathway:'school',health:90,wellbeing:68,cash:18000},...(age>=25?[{age:35,from:25,pathway:'work',finance,health:85,wellbeing:65,cash:18000}]:[])],story:{seen:memory.value==='love'?[{id:'love',age:24}]:[],flags}};}
function paint(){const age=Number(ageInput.value),state=fixture(age),activity=routine('player',age,time,'balance',routineContext(state,age));canvas.setAttribute('aria-label',t('Age {n}'.replace('{n}',age))+': '+t(activity.action));const rendered=drawWorld(canvas,state,age,time,'world',{homeFrame:camera.value==='home',animating:running});document.getElementById('study-note').textContent=rendered?.caption?t(rendered.caption):age<6?t(activity.action):age<20?t(activity.action)+' · '+t('The red school case stays with you when you move.'):t(branch.value==='city'?'Your rental home':'Family home')+' · '+t(activity.action)+' · '+t('Commute: {value} min / day'.replace('{value}',recordedCommute(state,age,'work')));}
memory.onchange=()=>{if(memory.value!=='routine'){ageInput.value=memory.value==='friend'?'17':'24';moment.value=memory.value==='friend'?'18':'49';}time=Number(moment.value);running=false;toggle.setAttribute('aria-pressed','false');dirty=true;};
for(const input of [ageInput,branch,moment,camera])input.onchange=()=>{time=Number(moment.value);running=false;toggle.setAttribute('aria-pressed','false');dirty=true;};
const stop=()=>{running=false;toggle.setAttribute('aria-pressed','false');};
toggle.onclick=()=>{if(preferences.motion||matchMedia('(prefers-reduced-motion: reduce)').matches){stop();return;}running=!running;toggle.setAttribute('aria-pressed',String(running));};
window.addEventListener('resize',()=>dirty=true);window.addEventListener('life-preferences',()=>{stop();dirty=true;});window.addEventListener('life-fonts-loaded',()=>dirty=true);window.addEventListener('life-settings-open',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
window.addEventListener('life-stage-art',()=>dirty=true);
initSettings();function tick(now){const dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(running){time+=dt;dirty=true;}if(dirty){paint();dirty=false;}requestAnimationFrame(tick);}requestAnimationFrame(tick);
